function ensureModal(){if(modal)return;modal=document.createElement('div');modal.className='flow-modal';modal.hidden=true;modal.innerHTML='<section class="flow-box" role="dialog" aria-modal="true" aria-labelledby="flowTitle"><div class="flow-head"><h3 id="flowTitle"></h3><button id="flowClose">关闭</button></div><div id="flowBody"></div><p id="flowStatus" role="status" aria-live="polite"></p></section>';document.body.append(modal);$('flowClose').onclick=close;modal.onclick=e=>{if(e.target===modal)close();};document.addEventListener('keydown',e=>{if(modal.hidden)return;if(e.key==='Escape')close();if(e.key==='Tab'){const list=[...modal.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&!x.hidden);if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0]?.focus();}}});}
