async function saveActions(proposed,actions,message,bundles=null){if(busy||!dataLoaded)return false;if(!actions.length){status('没有新增记录，已在项目中的账号会跳过。');return false;}busy=true;let started=false;modal?.querySelectorAll('button,input,select,textarea').forEach(e=>e.disabled=true);try{const packs=[];if(bundles){let pack=[];for(const bundle of bundles){if(pack.length+bundle.length>20){packs.push(pack);pack=[];}pack.push(...bundle);}if(pack.length)packs.push(pack);}else for(let i=0;i<actions.length;i+=20)packs.push(actions.slice(i,i+20));if(packs.length>1){status('正在预检多批次记录…');await send('/api/import/check',{revision,state:proposed});}for(let i=0;i<packs.length;i++){status('正在核对并保存第 '+(i+1)+' / '+packs.length+' 批，请保持网站运行。');const next=BulkImport.applyActions(state(),packs[i]);started=true;const d=await send('/api/state',{revision,state:next});revision=d.revision;fill(d.state||next);lastSaved=clone();}projectOptions();notify(message);return true;}catch(e){status(e.message+(started?'；可能有部分记录已保存。刷新后重新检查，已有账号会跳过。':'；未写入此次记录。'));notify($('flowStatus').textContent);if(started)try{await loadData();}catch{}return false;}finally{busy=false;modal?.querySelectorAll('button,input,select,textarea').forEach(e=>e.disabled=false);render();}}
